-- eval_tokens: Eval size per run
-- Tokens and minutes per complete eval run, summed over scenarios from the overall rows: mean per scenario run times scenarios times runs. Reads test.eval_runs (simulated data only).
with a as (select run_id, run_date, (metrics->'tokens'->>'mean')::numeric as tokens, (metrics->'tokens'->>'n')::int as scenarios, (metrics->'seconds'->>'mean')::numeric as seconds from test.eval_runs where scenario = 'ALL' and step = 'end_to_end'), n as (select run_id, max((metrics->'tokens'->>'n')::int) as runs from test.eval_runs where scenario <> 'ALL' and step = 'end_to_end' group by run_id) select a.run_id, a.run_date::text as run_date, round(a.tokens * a.scenarios * n.runs) as tokens, round(a.seconds / 60, 1) as minutes_per_run, a.scenarios, n.runs as runs_per_scenario from a join n using (run_id) order by a.run_id;
